    @Test fun tableTwoRow23() = assertEquals(SpeechCommand.None, SpeechCommandParser.parse("음 안내해 줘", listOf("A마트", "B마트")))
    @Test fun tableTwoRow24() = assertEquals(SpeechCommand.Confirm, SpeechCommandParser.parse("확정", listOf("A마트", "B마트")))
