    @Test fun tableTwoRow26() = assertEquals(SpeechCommand.None, SpeechCommandParser.parse("응 안내해 줘", listOf("A마트", "B마트")))
    @Test fun tableTwoRow27() = assertEquals(SpeechCommand.None, SpeechCommandParser.parse("안내해", listOf("A마트", "B마트")))
    @Test fun noMeansBack() = assertEquals(SpeechCommand.Back, SpeechCommandParser.parse("아니요"))
    @Test fun assentAfterNoIsNotWholeUtterance() = assertEquals(SpeechCommand.None, SpeechCommandParser.parse("아니요, 네"))
    @Test fun negatedPrefixCannotBeDiscardedForConfirm() = assertEquals(SpeechCommand.None, SpeechCommandParser.parse("안내하지 말고 출발"))
